const fs=require('fs');
const L=fs.readFileSync(process.argv[2],'utf8').split('\n');
function lcs(A,B){const n=A.length,m=B.length;const d=Array.from({length:n+1},()=>new Uint16Array(m+1));
for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)d[i][j]=A[i]===B[j]?d[i+1][j+1]+1:Math.max(d[i+1][j],d[i][j+1]);
const ops=[];let i=0,j=0;while(i<n&&j<m){if(A[i]===B[j]){ops.push(['=',A[i]]);i++;j++}else if(d[i+1][j]>=d[i][j+1]){ops.push(['-',A[i]]);i++}else{ops.push(['+',B[j]]);j++}}
while(i<n)ops.push(['-',A[i++]]);while(j<m)ops.push(['+',B[j++]]);return ops}
let i=0;
while(i<L.length){
 if(L[i].startsWith('@@')){console.log('\n'+L[i].slice(0,40));}
 if(L[i].startsWith('-')&&!L[i].startsWith('---')){const m=[],p=[];
  while(i<L.length&&L[i].startsWith('-'))m.push(L[i++].slice(1));
  while(i<L.length&&L[i].startsWith('+'))p.push(L[i++].slice(1));
  for(let k=0;k<Math.min(m.length,p.length);k++){
   const A=m[k].match(/\S+|\s+/g)||[],B=p[k].match(/\S+|\s+/g)||[];
   const ops=lcs(A,B);let out='',buf='',mode='=';
   // group
   const segs=[];for(const [t,s] of ops){if(segs.length&&segs[segs.length-1][0]===t)segs[segs.length-1][1]+=s;else segs.push([t,s])}
   // merge
   let res='';let q=0;
   while(q<segs.length){const [t,s]=segs[q];
     if(t==='='){res+=s.length<100?s:s.slice(0,40)+' … '+s.slice(-40);q++}
     else{let del='',ins='';while(q<segs.length&&segs[q][0]!=='='){if(segs[q][0]==='-')del+=segs[q][1];else ins+=segs[q][1];q++}
       res+='[-'+del+'-]{+'+ins+'+}'}}
   console.log(res);
  }
  continue}
 i++}
